add_filter( 'body_class', 'perfectpixel_slug_body_class' );

function perfectpixel_slug_body_class( $classes ) {
	if ( is_singular() ) {
		$post = get_queried_object();
		if ( $post instanceof WP_Post && $post->post_name ) {
			$classes[] = sanitize_html_class( $post->post_type . '-' . $post->post_name );
		}
	}
	return $classes;
}
